// Reads the patient's WhatsApp reply according to the step they are on.
const msg = $('Normalize Message').first().json;
const session = $input.all().map(i => i.json).find(r => r && r.sessionKey) || {};
const TZ = msg.timezone || 'Asia/Kolkata';

const DEPARTMENTS = [
  { code: 'GEN', name: 'General Medicine', icon: '🩺' },
  { code: 'CAR', name: 'Cardiology', icon: '❤️' },
  { code: 'DER', name: 'Dermatology', icon: '🧴' },
  { code: 'ORT', name: 'Orthopedics', icon: '🦴' },
  { code: 'PED', name: 'Pediatrics', icon: '👶' },
  { code: 'GYN', name: 'Gynecology & Obstetrics', icon: '🤰' },
  { code: 'ENT', name: 'ENT (Ear, Nose, Throat)', icon: '👂' },
  { code: 'OPH', name: 'Ophthalmology', icon: '👁️' },
  { code: 'NEU', name: 'Neurology', icon: '🧠' },
  { code: 'GAS', name: 'Gastroenterology', icon: '🍽️' },
  { code: 'DEN', name: 'Dentistry', icon: '🦷' },
  { code: 'PSY', name: 'Psychiatry', icon: '💭' },
  { code: 'URO', name: 'Urology', icon: '💧' },
  { code: 'PUL', name: 'Pulmonology', icon: '🫁' },
  { code: 'END', name: 'Endocrinology', icon: '🦋' },
];
const ILLNESSES = [
  { icon: '🤒', name: 'Fever / Cold / Flu' },
  { icon: '🤕', name: 'Pain or Injury' },
  { icon: '🧴', name: 'Skin problem' },
  { icon: '🍽️', name: 'Stomach / Digestion' },
  { icon: '🫁', name: 'Breathing / Chest issue' },
  { icon: '🩺', name: 'Routine check-up' },
  { icon: '🔁', name: 'Follow-up visit' },
];
const SLOTS = [
  { label: 'Morning 09:00 AM - 11:00 AM', start: '09:00', end: '11:00' },
  { label: 'Late Morning 11:00 AM - 01:00 PM', start: '11:00', end: '13:00' },
  { label: 'Afternoon 04:00 PM - 06:00 PM', start: '16:00', end: '18:00' },
  { label: 'Evening 06:00 PM - 08:00 PM', start: '18:00', end: '20:00' },
];

// Next 6 open days (Sundays closed)
const DAYS = [];
let cursor = DateTime.now().setZone(TZ).startOf('day');
while (DAYS.length < 6) {
  cursor = cursor.plus({ days: 1 });
  if (cursor.weekday === 7) continue;
  DAYS.push({
    day: cursor.toFormat('cccc'),
    date: cursor.toFormat('yyyy-MM-dd'),
    label: cursor.toFormat('cccc, dd LLL yyyy'),
  });
}

const menus = {
  dept: DEPARTMENTS.map((d, i) => `*${i + 1}.* ${d.icon} ${d.name}`).join('\n'),
  illness: ILLNESSES.map((d, i) => `*${i + 1}.* ${d.icon} ${d.name}`).join('\n'),
  day: DAYS.map((d, i) => `*${i + 1}.* 📅 ${d.label}`).join('\n'),
  time: SLOTS.map((s, i) => `*${i + 1}.* ⏰ ${s.label}`).join('\n'),
};
const PROMPTS = {
  NAME: '👤 Please type your *full name* (letters only).',
  AGE: '🎂 Please enter your *age in years* (for example: 34).',
  DEPARTMENT: `🏥 Please reply with a number *1-${DEPARTMENTS.length}*:\n\n${menus.dept}`,
  ILLNESS: `🤒 Reply with a number *1-${ILLNESSES.length}*, or simply type your concern:\n\n${menus.illness}`,
  DAY: `📅 Please reply with a number *1-${DAYS.length}*:\n\n${menus.day}`,
  TIME: `⏰ Please reply with a number *1-${SLOTS.length}*:\n\n${menus.time}`,
  CONFIRM: '✅ Reply *1* to Confirm or *2* to Cancel.',
};

const text = (msg.text || '').trim();
const lower = text.toLowerCase();
const RESTART = ['hi', 'hii', 'hello', 'hey', 'hai', 'start', 'menu', 'restart', 'book', 'appointment', 'book appointment'];

let step = session.step || 'START';
if (step === 'DONE' || RESTART.includes(lower)) step = 'START';

const n = /^\d{1,3}$/.test(text) ? parseInt(text, 10) : NaN;
let route = step;
let pick = {};

switch (step) {
  case 'NAME':
    if (/^[\p{L}][\p{L} .'-]{1,59}$/u.test(text)) {
      pick.name = text.replace(/\s+/g, ' ').split(' ')
        .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
    } else route = 'INVALID';
    break;
  case 'AGE':
    if (n >= 0 && n <= 120) pick.age = n; else route = 'INVALID';
    break;
  case 'DEPARTMENT':
    if (n >= 1 && n <= DEPARTMENTS.length) {
      pick.departmentCode = DEPARTMENTS[n - 1].code;
      pick.department = DEPARTMENTS[n - 1].name;
    } else route = 'INVALID';
    break;
  case 'ILLNESS':
    if (n >= 1 && n <= ILLNESSES.length) pick.illness = ILLNESSES[n - 1].name;
    else if (isNaN(n) && /^[\p{L}][\p{L}0-9 ,.'()\/-]{2,80}$/u.test(text)) pick.illness = text;
    else route = 'INVALID';
    break;
  case 'DAY':
    if (n >= 1 && n <= DAYS.length) {
      pick.day = DAYS[n - 1].day; pick.date = DAYS[n - 1].date; pick.dateLabel = DAYS[n - 1].label;
    } else route = 'INVALID';
    break;
  case 'TIME':
    if (n >= 1 && n <= SLOTS.length) {
      pick.timeSlot = SLOTS[n - 1].label; pick.timeStart = SLOTS[n - 1].start; pick.timeEnd = SLOTS[n - 1].end;
    } else route = 'INVALID';
    break;
  case 'CONFIRM':
    if (['1', 'yes', 'y', 'confirm'].includes(lower)) route = 'CONFIRM_YES';
    else if (['2', 'no', 'n', 'cancel'].includes(lower)) route = 'CONFIRM_NO';
    else route = 'INVALID';
    break;
  default:
    route = 'START';
}

const carried = {};
for (const k of ['name', 'age', 'departmentCode', 'department', 'illness', 'day', 'date', 'dateLabel', 'timeSlot', 'timeStart', 'timeEnd']) {
  carried[k] = session[k] ?? '';
}

return [{ json: {
  ...msg,
  ...carried,
  step,
  route,
  pick,
  menus,
  retryPrompt: `⚠️ Sorry, I didn't catch that.\n\n${PROMPTS[step] || PROMPTS.NAME}`,
} }];

