// Token = DEPT-DDMM-SEQ, numbered per department per day.
const p = $('Parse Input').first().json;
const TZ = p.timezone || 'Asia/Kolkata';
const existing = $input.all().map(i => i.json).filter(r => r && r.token);
const seq = existing.length + 1;
const date = String(p.date);
const day = DateTime.fromISO(date, { zone: TZ });
const token = `${p.departmentCode}-${day.toFormat('ddLL')}-${String(seq).padStart(3, '0')}`;
const start = DateTime.fromISO(`${date}T${p.timeStart}`, { zone: TZ });
const end = DateTime.fromISO(`${date}T${p.timeEnd}`, { zone: TZ });
return [{ json: {
  token,
  seq,
  tokenKey: `${p.departmentCode}-${date}`,
  startISO: start.toISO(),
  endISO: end.toISO(),
} }];

