// Department staff reply:  /done CAR-0211-003
const m = $json.message || {};
const text = (m.text || '').trim();
const match = text.match(/^\/done(?:@\w+)?\s+([A-Za-z]{3}-\d{4}-\d{3})$/);
if (!match) return [];
return [{ json: {
  token: match[1].toUpperCase(),
  chatId: m.chat.id,
  completedBy: (m.from && m.from.first_name) || 'Staff',
  completedAt: DateTime.now().toISO(),
} }];
